# ---------------------------------------------------------------------------
# Utilities
# ---------------------------------------------------------------------------


def cs_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def slugify(name: str) -> str:
    s = name.lower().replace("'", "")
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return s


def join_sentences(*parts: str) -> str:
    return " ".join(p.strip() for p in parts if p and p.strip())


def join_paragraphs(*parts: str) -> str:
    return "\n\n".join(p.strip() for p in parts if p and p.strip())


# ---------------------------------------------------------------------------
# Lore template engine
# ---------------------------------------------------------------------------


def build_species_lore(
    name: str,
    homeworld: str,
    classification: str,
    *,
    origin_detail: str,
    ancient_detail: str,
    modern_detail: str,
    conflict_detail: str,
    biology_detail: str,
    culture_detail: str,
    impact_detail: str,
    events: list[str],
    affiliations: list[str],
    timeline: list[tuple[str, str]],
) -> dict:
    origins = join_sentences(
        f"The {name} ({classification.lower()}) trace their deepest roots to {homeworld}, where fossil beds, oral traditions, and surviving ruins suggest millennia of uninterrupted development.",
        origin_detail,
        f"Galactic surveyors first catalogued {name} populations during the expansion of the Old Republic, though local records often predate offworld contact by thousands of years.",
        f"Across films, Clone Wars, Rebels, Mandalorian, Ahsoka, KOTOR, KOTOR II, The Old Republic, and Sith Empire chronicles, {name} history is treated as foundational rather than peripheral.",
    )
    ancient = join_sentences(
        f"In the Ancient Era and early Old Republic, {name} societies on {homeworld} established trade routes, planetary defense, and Force traditions that later empires would inherit or suppress.",
        ancient_detail,
        f"Archaeologists still debate how much of modern {name} identity was shaped by Rakatan influence, Infinite Empire collapse, and the long shadow of the Sith.",
        f"High Republic archives mention {name} delegations, warriors, and artisans whose contributions were later rediscovered only through holocrons and battlefield inscriptions.",
    )
    modern = join_sentences(
        f"From the Clone Wars through the Imperial Era and into the New Republic, {name} diaspora communities appeared on every major trade lane and war front.",
        modern_detail,
        f"Mandalorian-era intelligence briefings and Ahsoka-era reconstructions confirm that {name} networks remained active even when their homeworld fell under occupation or blockade.",
        f"Sequel-era historians now treat {name} migration patterns as a map of galactic trauma and renewal, not mere demographic noise.",
    )
    conflicts = join_sentences(
        f"{name} fought in the galaxy's defining wars—not only as soldiers but as spies, healers, smugglers, and refugees whose choices shifted battle outcomes.",
        conflict_detail,
        f"KOTOR and KOTOR II document {name} involvement in the Jedi Civil War, while TOR and Sith Empire materials show parallel struggles against the Eternal Empire and Dread Masters.",
        f"Rebels and Clone Wars episodes repeatedly demonstrate that a single {name} leader can rally a sector or, conversely, expose a conspiracy that topples a fleet.",
    )
    biology = join_sentences(
        f"Biologically, the {name} display traits typical of {classification.lower()} life adapted to {homeworld}'s gravity, atmosphere, and seasonal extremes.",
        biology_detail,
        f"Medics note that {name} physiology interacts with cybernetics, clone templates, and Force healing in ways that are well documented in Republic medical journals.",
        f"Geneticists argue that {name} resilience under occupation and exile explains much of their survival rate across the Rim and Unknown Regions.",
    )
    culture = join_sentences(
        f"{name} culture encodes memory through art, ritual, cuisine, and language dialects that survive even when homeworld cities are bombed flat.",
        culture_detail,
        f"Both Jedi and Sith sources acknowledge {name} spiritual practices, though each tradition interprets those practices through its own doctrine of attachment and power.",
        f"Living {name} communities on Coruscant, Nar Shaddaa, and Ferrix-style industrial worlds prove that culture is portable when homeworld sovereignty is not.",
    )
    impact = join_sentences(
        f"The galactic impact of the {name} exceeds what population tables suggest: their merchants, admirals, crime lords, and senators rewrote trade law and fleet doctrine.",
        impact_detail,
        f"Historians credit {name} innovators with breakthroughs in hyperspace navigation, droid ethics debates, and post-Imperial reconciliation councils.",
        f"Whether aligned with the Republic, the Separatists, the Rebellion, or independent Mandalorian clans, {name} choices remain reference points in every major era study.",
    )
    return {
        "origins": origins,
        "ancient": ancient,
        "modern": modern,
        "conflicts": conflicts,
        "biology": biology,
        "culture": culture,
        "impact": impact,
        "events": events,
        "affiliations": affiliations,
        "timeline": [{"era": era, "event": event} for era, event in timeline],
    }


def build_settlement_lore(
    name: str,
    planet: str,
    settlement_type: str,
    *,
    origin_detail: str,
    ancient_detail: str,
    modern_detail: str,
    conflict_detail: str,
    economy_detail: str,
    culture_detail: str,
    impact_detail: str,
    events: list[str],
    affiliations: list[str],
    timeline: list[tuple[str, str]],
) -> dict:
    origins = join_sentences(
        f"{name} began as a {settlement_type.lower()} anchor on {planet}, positioned where water, ore, hyperspace lanes, or sacred geography forced travelers to stop.",
        origin_detail,
        f"Early survey maps from the Old Republic era list {name} as a mandatory customs point for sector governors and Jedi exploration teams.",
        f"Films, Clone Wars, Rebels, Mandalorian, Ahsoka, KOTOR, KOTOR II, TOR, and Sith Empire narratives all treat {name} as more than scenery—it is a decision point.",
    )
    ancient = join_sentences(
        f"Ancient and pre-Republic layers beneath {name} include buried fortresses, Rakatan relics, and Sith ward-stones that still disrupt modern sensors.",
        ancient_detail,
        f"High Republic pathfinders logged {name} as a waypoint during the Great Hyperspace Rush, leaving beacon towers that later wars repurposed as artillery spotters.",
        f"Local archives recovered from {planet} suggest {name} once governed trade policy for entire subsectors before centralization on Coruscant.",
    )
    modern = join_sentences(
        f"In the modern era, {name} expanded through prefab districts, orbital elevators, and refugee camps that fused multiple species into a single urban rhythm.",
        modern_detail,
        f"Mandalorian-era bounties and Ahsoka-era investigations repeatedly lead back to {name} because its ports lack the scrutiny of Core World bureaucracy.",
        f"New Republic planners studied {name} as a template for rebuilding settlements after the Imperial collapse, citing both its failures and its innovations.",
    )
    conflicts = join_sentences(
        f"{name} has been invaded, liberated, blockaded, and rebuilt more times than most planetary capitals, making its streets a palimpsest of battle damage.",
        conflict_detail,
        f"Clone Wars dossiers mark {name} as strategically vital; Imperial Era governors exploited that same geography to punish rebellious populations.",
        f"KOTOR-era records and TOR-era campaign logs show earlier iterations of the same struggle—control of {name} meant control of {planet}.",
    )
    economy = join_sentences(
        f"The economy of {name} runs on layered industries: docking fees, black-market mediation, sacred tourism, factory output, or casino finance depending on the era.",
        economy_detail,
        f"Trade guilds from the Techno Union to the Mining Guild filed competing claims on {name} infrastructure during the late Republic.",
        f"Post-war reconstruction funds often bypass {name} officially while flowing through its shadow banks—an open secret among Bothan analysts.",
    )
    culture = join_sentences(
        f"Cultural life in {name} mixes planetary tradition with imported habits from every species that ever missed a connection and stayed.",
        culture_detail,
        f"Music, food, and festival calendars in {name} are used by rebels to signal safe houses and by Imperials to track dissident networks.",
        f"Jedi historians note that some of the galaxy's quietest acts of mercy—evacuations, forged transit papers, hidden healers—were organized in {name} back alleys.",
    )
    impact = join_sentences(
        f"{name} influences galactic history disproportionately because leaders, smugglers, and prophets treat it as neutral ground until it suddenly is not.",
        impact_detail,
        f"Scenes set in {name} across the saga often mark turning points: treaties signed, betrayals exposed, or the first shot of a regional war.",
        f"Settlement planners across the Rim still cite {name} when arguing for open ports versus fortified capitals—a debate renewed after every occupation.",
    )
    return {
        "origins": origins,
        "ancient": ancient,
        "modern": modern,
        "conflicts": conflicts,
        "economy": economy,
        "culture": culture,
        "impact": impact,
        "events": events,
        "affiliations": affiliations,
        "timeline": [{"era": era, "event": event} for era, event in timeline],
    }


def sp(
    name: str,
    homeworld: str,
    classification: str,
    description: str,
    color: str,
    sources: str,
    silhouette: str,
    lore_kwargs: dict,
) -> dict:
    slug = slugify(name)
    lore = build_species_lore(name, homeworld, classification, **lore_kwargs)
    return {
        "name": name,
        "slug": slug,
        "homeworld": homeworld,
        "classification": classification,
        "description": description,
        "color": color,
        "sources": sources,
        "silhouette": silhouette,
        "lore": lore,
    }


def st(
    name: str,
    planet: str,
    settlement_type: str,
    description: str,
    color: str,
    sources: str,
    skyline: str,
    lore_kwargs: dict,
) -> dict:
    slug = slugify(name)
    lore = build_settlement_lore(name, planet, settlement_type, **lore_kwargs)
    return {
        "name": name,
        "slug": slug,
        "planet": planet,
        "settlement_type": settlement_type,
        "description": description,
        "color": color,
        "sources": sources,
        "skyline": skyline,
        "lore": lore,
    }


