# ---------------------------------------------------------------------------
# Profile and C# writers
# ---------------------------------------------------------------------------


def build_species_profile(entry: dict) -> dict:
    lore = entry["lore"]
    overview = join_sentences(
        f"{entry['name']} ({entry['classification']}) is native to {entry['homeworld']} and ranks among the most consequential species in galactic history.",
        entry["description"],
    )
    history = join_paragraphs(lore["origins"], lore["ancient"], lore["modern"], lore["conflicts"])
    significance = join_paragraphs(lore["biology"], lore["culture"], lore["impact"])
    return {
        "overview": overview,
        "history": history,
        "significance": significance,
        "notableEvents": lore["events"],
        "affiliations": lore["affiliations"],
        "timeline": lore["timeline"],
        "gallery": [
            {"path": f"/images/species/{entry['slug']}-scene.webp", "caption": f"Cinematic illustration — {entry['name']}"},
        ],
    }


def build_settlement_profile(entry: dict) -> dict:
    lore = entry["lore"]
    overview = join_sentences(
        f"{entry['name']} is a {entry['settlement_type'].lower()} on {entry['planet']}, documented across {entry['sources']}.",
        entry["description"],
    )
    history = join_paragraphs(lore["origins"], lore["ancient"], lore["modern"], lore["conflicts"])
    significance = join_paragraphs(lore["economy"], lore["culture"], lore["impact"])
    return {
        "overview": overview,
        "history": history,
        "significance": significance,
        "notableEvents": lore["events"],
        "affiliations": lore["affiliations"],
        "timeline": lore["timeline"],
        "gallery": [
            {"path": f"/images/settlements/{entry['slug']}-scene.webp", "caption": f"Cinematic illustration — {entry['name']}"},
        ],
    }


def write_species_cs(entries: list[dict]) -> None:
    lines = [
        "using StarWars.Models;",
        "",
        "namespace StarWars.Data;",
        "",
        "public static class SpeciesData",
        "{",
        "    public static IReadOnlyList<Species> SpeciesList { get; } =",
        "    [",
    ]
    for e in entries:
        lines.extend([
            "        new()",
            "        {",
            f'            Name = "{cs_escape(e["name"])}",',
            f'            Slug = "{cs_escape(e["slug"])}",',
            f'            Route = "species/{cs_escape(e["slug"])}",',
            f'            Homeworld = "{cs_escape(e["homeworld"])}",',
            f'            Classification = "{cs_escape(e["classification"])}",',
            f'            Description = "{cs_escape(e["description"])}",',
            f'            Color = "{cs_escape(e["color"])}",',
            f'            Sources = "{cs_escape(e["sources"])}",',
            "        },",
        ])
    lines.extend([
        "    ];",
        "",
        "    public static Species? GetBySlug(string slug) =>",
        "        SpeciesList.FirstOrDefault(s => s.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));",
        "}",
        "",
    ])
    SPECIES_CS.write_text("\n".join(lines))


def write_settlement_cs(entries: list[dict]) -> None:
    lines = [
        "using StarWars.Models;",
        "",
        "namespace StarWars.Data;",
        "",
        "public static class SettlementData",
        "{",
        "    public static IReadOnlyList<Settlement> Settlements { get; } =",
        "    [",
    ]
    for e in entries:
        lines.extend([
            "        new()",
            "        {",
            f'            Name = "{cs_escape(e["name"])}",',
            f'            Slug = "{cs_escape(e["slug"])}",',
            f'            Route = "settlements/{cs_escape(e["slug"])}",',
            f'            Planet = "{cs_escape(e["planet"])}",',
            f'            SettlementType = "{cs_escape(e["settlement_type"])}",',
            f'            Description = "{cs_escape(e["description"])}",',
            f'            Color = "{cs_escape(e["color"])}",',
            f'            Sources = "{cs_escape(e["sources"])}",',
            "        },",
        ])
    lines.extend([
        "    ];",
        "",
        "    public static Settlement? GetBySlug(string slug) =>",
        "        Settlements.FirstOrDefault(s => s.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));",
        "}",
        "",
    ])
    SETTLEMENT_CS.write_text("\n".join(lines))


