def main() -> None:
    from species_catalog_additions import ADDITIONAL_SPECIES
    from settlement_catalog_additions import ADDITIONAL_SETTLEMENTS

    all_species = SPECIES + ADDITIONAL_SPECIES
    all_settlements = SETTLEMENTS + ADDITIONAL_SETTLEMENTS

    SPECIES_IMAGES.mkdir(parents=True, exist_ok=True)
    SETTLEMENT_IMAGES.mkdir(parents=True, exist_ok=True)
    SPECIES_PROFILES.mkdir(parents=True, exist_ok=True)
    SETTLEMENT_PROFILES.mkdir(parents=True, exist_ok=True)

    write_species_cs(all_species)
    write_settlement_cs(all_settlements)

    for entry in all_species:
        slug = entry["slug"]
        accent = entry["color"]
        kind = entry["silhouette"]
        (SPECIES_IMAGES / f"{slug}.svg").write_text(
            svg_wrap(
                entry["name"],
                accent,
                species_body(kind, False, entry["name"], accent, entry["classification"]),
                slug,
            )
        )
        (SPECIES_IMAGES / f"{slug}-scene.svg").write_text(
            svg_wrap(
                f"{entry['name']} — scene",
                accent,
                species_body(kind, True, entry["name"], accent, entry["classification"]),
                f"{slug}-scene",
            )
        )
        (SPECIES_PROFILES / f"{slug}.json").write_text(
            json.dumps(build_species_profile(entry), indent=2, ensure_ascii=False) + "\n"
        )

    for entry in all_settlements:
        slug = entry["slug"]
        accent = entry["color"]
        kind = entry["skyline"]
        (SETTLEMENT_IMAGES / f"{slug}.svg").write_text(
            svg_wrap(
                entry["name"],
                accent,
                settlement_body(kind, False, entry["name"], accent, entry["settlement_type"]),
                slug,
            )
        )
        (SETTLEMENT_IMAGES / f"{slug}-scene.svg").write_text(
            svg_wrap(
                f"{entry['name']} — scene",
                accent,
                settlement_body(kind, True, entry["name"], accent, entry["settlement_type"]),
                f"{slug}-scene",
            )
        )
        (SETTLEMENT_PROFILES / f"{slug}.json").write_text(
            json.dumps(build_settlement_profile(entry), indent=2, ensure_ascii=False) + "\n"
        )

    species_files = len(all_species) * 4
    settlement_files = len(all_settlements) * 4
    print(f"Generated {len(all_species)} species")
    print(f"Generated {len(all_settlements)} settlements")
    print("  SpeciesData.cs + SettlementData.cs")
    print(f"  Species assets:   {len(all_species)} icons, {len(all_species)} scenes, {len(all_species)} profiles")
    print(f"  Settlement assets: {len(all_settlements)} icons, {len(all_settlements)} scenes, {len(all_settlements)} profiles")
    print(f"  Total files: {2 + species_files + settlement_files}")


if __name__ == "__main__":
    main()
